import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void merge(List<Integer> arr, int l, int m, int r) {
        int n1 = m - l + 1;
        int n2 = r - m;
        List<Integer> L = new ArrayList<>(n1);
        List<Integer> R = new ArrayList<>(n2);
        for (int i = 0; i < n1; ++i) L.add(arr.get(l + i));
        for (int j = 0; j < n2; ++j) R.add(arr.get(m + 1 + j));
        int i = 0, j = 0, k = l;
        while (i < n1 && j < n2) {
            if (L.get(i) <= R.get(j)) {
                arr.set(k++, L.get(i++));
            } else {
                arr.set(k++, R.get(j++));
            }
        }
        while (i < n1) arr.set(k++, L.get(i++));
        while (j < n2) arr.set(k++, R.get(j++));
    }

    public static void mergeSort(List<Integer> arr, int l, int r) {
        if (l < r) {
            int m = l + (r - l) / 2;
            mergeSort(arr, l, m);
            mergeSort(arr, m + 1, r);
            merge(arr, l, m, r);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        List<Integer> a = new ArrayList<>(n);
        for (int i = 0; i < n; ++i) {
            a.add(scanner.nextInt());
        }
        mergeSort(a, 0, n - 1);
        if (n == 1) {
            System.out.println(a.get(0));
        } else {
            int mid = n / 2;
            System.out.println(a.get(mid));
        }
        scanner.close();
    }
}
